import {
  bigint,
  boolean,
  customType,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Better Auth tables (user, session, account, verification, organization, member, invitation).
// Generated by `pnpm dlx auth@<better-auth version> generate`; never edit by hand.
export * from './auth-schema';

// Every tenant-owned table below carries org_id (a Better Auth organization id). Application code
// reaches them only through forOrg() in ./tenant.ts, never through unscoped queries.

const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => 'bytea' });

const timestamps = {
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', { withTimezone: true })
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date()),
};

export const sites = pgTable(
  'sites',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    name: text('name').notNull(),
    // Address we connect to (as entered, normalized). homeUrl is what WordPress reports.
    url: text('url').notNull(),
    homeUrl: text('home_url'),
    status: text('status', { enum: ['connected', 'disconnected', 'error'] })
      .default('connected')
      .notNull(),
    statusMessage: text('status_message'),
    lastCheckedAt: timestamp('last_checked_at', { withTimezone: true }),
    // Which REST URL style the site answers on (see @tricity/wp-client); null until first contact.
    routeStyle: text('route_style', { enum: ['pretty', 'query'] }),
    connectionId: text('connection_id'),
    // Connector token, AES-GCM encrypted with the platform key. The plain token is never stored.
    tokenCiphertext: text('token_ciphertext'),
    wpVersion: text('wp_version'),
    pluginVersion: text('plugin_version'),
    seoPlugin: text('seo_plugin', { enum: ['yoast', 'rankmath', 'aioseo'] }),
    // Site-wide instructions prepended to every content/design prompt.
    contentPrompt: text('content_prompt').default('').notNull(),
    designPrompt: text('design_prompt').default('').notNull(),
    ...timestamps,
  },
  (t) => [uniqueIndex('sites_org_url_idx').on(t.orgId, t.url)],
);

export const templates = pgTable(
  'templates',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    kind: text('kind', { enum: ['content', 'design'] }).notNull(),
    name: text('name').notNull(),
    description: text('description').default('').notNull(),
    prompt: text('prompt').notNull(),
    ...timestamps,
  },
  (t) => [index('templates_org_kind_idx').on(t.orgId, t.kind)],
);

// One article request, from the wizard, auto-blogging, or MCP. Input/output shapes live in
// @tricity/core (GenerationInput, GenerationOutput).
export const generations = pgTable(
  'generations',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    source: text('source', { enum: ['wizard', 'autoblog', 'mcp'] }).notNull(),
    status: text('status', {
      enum: ['queued', 'generating', 'ready', 'publishing', 'published', 'failed'],
    }).notNull(),
    topic: text('topic').notNull(),
    input: jsonb('input').notNull(),
    output: jsonb('output'),
    seoScore: integer('seo_score'),
    wpPostId: integer('wp_post_id'),
    wpPostUrl: text('wp_post_url'),
    wpPostStatus: text('wp_post_status'),
    error: text('error'),
    createdBy: text('created_by'),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    ...timestamps,
  },
  (t) => [index('generations_org_site_created_idx').on(t.orgId, t.siteId, t.createdAt)],
);

// Generated images awaiting review/publish. Bytes are already optimized (WebP).
export const generationImages = pgTable(
  'generation_images',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    generationId: uuid('generation_id')
      .notNull()
      .references(() => generations.id, { onDelete: 'cascade' }),
    // 0 = featured image; 1..n = inline images, matching tcw-image://n placeholders in the HTML.
    slot: integer('slot').notNull(),
    prompt: text('prompt').notNull(),
    alt: text('alt').notNull(),
    mimeType: text('mime_type').notNull(),
    width: integer('width').notNull(),
    height: integer('height').notNull(),
    data: bytea('data').notNull(),
    wpMediaId: integer('wp_media_id'),
    wpUrl: text('wp_url'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [uniqueIndex('generation_images_slot_idx').on(t.generationId, t.slot)],
);

export const autoblogProfiles = pgTable(
  'autoblog_profiles',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    enabled: boolean('enabled').default(false).notNull(),
    // assist = always draft; guarded = publish only if SEO score >= threshold; autopilot = always publish.
    mode: text('mode', { enum: ['assist', 'guarded', 'autopilot'] })
      .default('assist')
      .notNull(),
    threshold: integer('threshold').default(70).notNull(),
    // Cron pattern evaluated in `timezone`.
    schedule: text('schedule').default('0 9 * * *').notNull(),
    timezone: text('timezone').default('UTC').notNull(),
    // Generation settings applied to every run (same shape as the wizard's options).
    settings: jsonb('settings').notNull(),
    ...timestamps,
  },
  (t) => [uniqueIndex('autoblog_profiles_site_idx').on(t.siteId)],
);

export const autoblogTopics = pgTable(
  'autoblog_topics',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    topic: text('topic').notNull(),
    keywords: text('keywords').default('').notNull(),
    status: text('status', { enum: ['queued', 'used', 'failed'] })
      .default('queued')
      .notNull(),
    generationId: uuid('generation_id').references(() => generations.id, { onDelete: 'set null' }),
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [index('autoblog_topics_site_status_idx').on(t.siteId, t.status, t.createdAt)],
);

// A workspace's own AI provider key (BYOK). Used instead of the platform key for that provider.
export const aiCredentials = pgTable(
  'ai_credentials',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    provider: text('provider', { enum: ['anthropic', 'openai'] }).notNull(),
    // AES-GCM encrypted with the platform key; only the last four characters are ever shown.
    keyCiphertext: text('key_ciphertext').notNull(),
    keyLast4: text('key_last4').notNull(),
    createdBy: text('created_by'),
    ...timestamps,
  },
  (t) => [uniqueIndex('ai_credentials_org_provider_idx').on(t.orgId, t.provider)],
);

// Bearer keys for the MCP endpoint. Only a SHA-256 hash is stored.
export const mcpKeys = pgTable(
  'mcp_keys',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    userId: text('user_id').notNull(),
    name: text('name').notNull(),
    prefix: text('prefix').notNull(),
    keyHash: text('key_hash').notNull(),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [uniqueIndex('mcp_keys_hash_idx').on(t.keyHash)],
);

// One row per billable AI call. Billing is not built yet, but usage is recorded from day one.
export const usageEvents = pgTable(
  'usage_events',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: text('org_id').notNull(),
    siteId: uuid('site_id').references(() => sites.id, { onDelete: 'set null' }),
    kind: text('kind', { enum: ['text', 'image'] }).notNull(),
    provider: text('provider').notNull(),
    model: text('model').notNull(),
    // Whose key paid for the call: ours, or the org's own key (BYOK, later).
    credentialOwner: text('credential_owner', { enum: ['platform', 'org'] }).notNull(),
    inputTokens: integer('input_tokens').default(0).notNull(),
    outputTokens: integer('output_tokens').default(0).notNull(),
    images: integer('images').default(0).notNull(),
    // 0 when the model has no price in the registry.
    costMicroUsd: bigint('cost_micro_usd', { mode: 'number' }).default(0).notNull(),
    generationId: uuid('generation_id'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [index('usage_events_org_created_idx').on(t.orgId, t.createdAt)],
);

export type Site = typeof sites.$inferSelect;
export type NewSite = typeof sites.$inferInsert;
export type Template = typeof templates.$inferSelect;
export type Generation = typeof generations.$inferSelect;
export type GenerationImage = typeof generationImages.$inferSelect;
export type AutoblogProfile = typeof autoblogProfiles.$inferSelect;
export type AutoblogTopic = typeof autoblogTopics.$inferSelect;
export type McpKey = typeof mcpKeys.$inferSelect;
export type AiCredential = typeof aiCredentials.$inferSelect;
export type UsageEvent = typeof usageEvents.$inferSelect;
export type NewUsageEvent = typeof usageEvents.$inferInsert;
